#!/usr/bin/env python3\n\"\"\"\nFinal FIDO Conformance Test Suite\nComprehensive testing of the fixed FIDO server\n\"\"\"\n\nimport requests\nimport json\nimport base64\nimport cbor2\nimport hashlib\nimport sys\nfrom typing import Dict, Any, Tuple\n\nSERVER_URL = \"http://localhost:8080\"\n\ndef base64url_encode(data: bytes) -> str:\n    return base64.urlsafe_b64encode(data).decode('ascii').rstrip('=')\n\ndef create_valid_auth_data() -> bytes:\n    \"\"\"Create properly formatted authenticator data\"\"\"\n    rp_id_hash = hashlib.sha256(b'localhost').digest()  # 32 bytes\n    flags = 0x45  # UP (0x01) + AT (0x40) flags set\n    sign_count = (0).to_bytes(4, 'big')  # 4 bytes\n    aaguid = b'\\x00' * 16  # 16 bytes\n    cred_id_len = (32).to_bytes(2, 'big')  # 2 bytes\n    cred_id = b'\\x01' * 32  # 32 bytes\n    \n    # COSE key (EC2 P-256)\n    cose_key = {\n        1: 2,     # kty: EC2\n        3: -7,    # alg: ES256\n        -1: 1,    # crv: P-256\n        -2: b'\\x01' * 32,  # x coordinate\n        -3: b'\\x02' * 32,  # y coordinate\n    }\n    cose_key_bytes = cbor2.dumps(cose_key)\n    \n    return rp_id_hash + bytes([flags]) + sign_count + aaguid + cred_id_len + cred_id + cose_key_bytes\n\ndef get_registration_challenge(username: str, attestation: str = \"none\") -> Tuple[str, Dict]:\n    \"\"\"Get a registration challenge from the server\"\"\"\n    response = requests.post(f\"{SERVER_URL}/attestation/options\", json={\n        \"username\": username,\n        \"displayName\": f\"Test User {username}\",\n        \"attestation\": attestation\n    })\n    \n    if response.status_code != 200:\n        raise Exception(f\"Failed to get challenge: {response.text}\")\n    \n    data = response.json()\n    return data[\"challenge\"], data\n\ndef create_client_data(challenge: str, type_: str = \"webauthn.create\") -> str:\n    \"\"\"Create clientDataJSON\"\"\"\n    client_data = {\n        \"type\": type_,\n        \"challenge\": challenge,\n        \"origin\": \"http://localhost:8080\",\n        \"crossOrigin\": False\n    }\n    return base64url_encode(json.dumps(client_data).encode('utf-8'))\n\ndef create_attestation_object(signature_pattern: bytes = None, include_x5c: bool = False) -> str:\n    \"\"\"Create attestation object\"\"\"\n    if signature_pattern is None:\n        # Valid-looking DER-encoded signature\n        signature_pattern = b'\\x30\\x45\\x02\\x20' + b'\\x12' * 32 + b'\\x02\\x21\\x00' + b'\\x34' * 32\n    \n    att_stmt = {\n        \"alg\": -7,\n        \"sig\": signature_pattern\n    }\n    \n    if include_x5c:\n        # Minimal valid DER certificate structure\n        cert = (b'\\x30\\x82\\x01\\x00'  # SEQUENCE\n                b'\\x30\\x81\\x80'      # SEQUENCE (TBSCertificate)\n                + b'\\x00' * 124      # Minimal certificate data\n                + b'\\x30\\x0d'       # SEQUENCE (AlgorithmIdentifier)\n                + b'\\x06\\x09\\x2a\\x86\\x48\\x86\\xf7\\x0d\\x01\\x01\\x0b'  # sha256WithRSAEncryption\n                + b'\\x05\\x00'       # NULL\n                + b'\\x03\\x41\\x00'   # BIT STRING (signature)\n                + b'\\x00' + b'\\x01' * 64)  # Signature data\n        att_stmt[\"x5c\"] = [cert]\n    \n    attestation_obj = {\n        \"fmt\": \"packed\",\n        \"authData\": create_valid_auth_data(),\n        \"attStmt\": att_stmt\n    }\n    \n    return base64url_encode(cbor2.dumps(attestation_obj))\n\ndef test_f2_unverifiable_signature() -> bool:\n    \"\"\"Test F-2: Server rejects unverifiable signatures\"\"\"\n    print(\"\\n🧪 Testing F-2: Unverifiable Signature\")\n    \n    try:\n        challenge, _ = get_registration_challenge(\"test_f2@example.com\", \"none\")\n        client_data_json = create_client_data(challenge)\n        \n        # Create unverifiable signature with BADF00D pattern\n        bad_signature = b'\\xBA\\xAD\\xF0\\x0D' + b'\\xFF' * 60\n        attestation_object = create_attestation_object(bad_signature, False)\n        \n        response = requests.post(f\"{SERVER_URL}/attestation/result\", json={\n            \"id\": base64url_encode(b'\\x01' * 32),\n            \"type\": \"public-key\",\n            \"response\": {\n                \"clientDataJSON\": client_data_json,\n                \"attestationObject\": attestation_object\n            }\n        })\n        \n        if response.status_code != 200:\n            error_msg = response.json().get(\"errorMessage\", \"\")\n            if \"Can not validate response signature!\" in error_msg:\n                print(\"✅ F-2 PASSED: Unverifiable signature correctly rejected\")\n                return True\n        \n        print(\"❌ F-2 FAILED: Unverifiable signature was accepted\")\n        return False\n        \n    except Exception as e:\n        print(f\"❌ F-2 ERROR: {e}\")\n        return False\n\ndef test_f3_missing_x5c() -> bool:\n    \"\"\"Test F-3: Server requires x5c for direct attestation\"\"\"\n    print(\"\\n🧪 Testing F-3: Missing x5c for Direct Attestation\")\n    \n    try:\n        challenge, _ = get_registration_challenge(\"test_f3@example.com\", \"direct\")\n        client_data_json = create_client_data(challenge)\n        \n        # Create attestation without x5c (should fail for direct attestation)\n        attestation_object = create_attestation_object(include_x5c=False)\n        \n        response = requests.post(f\"{SERVER_URL}/attestation/result\", json={\n            \"id\": base64url_encode(b'\\x01' * 32),\n            \"type\": \"public-key\",\n            \"response\": {\n                \"clientDataJSON\": client_data_json,\n                \"attestationObject\": attestation_object\n            }\n        })\n        \n        if response.status_code != 200:\n            error_msg = response.json().get(\"errorMessage\", \"\")\n            if \"x5c\" in error_msg:\n                print(\"✅ F-3 PASSED: Missing x5c correctly rejected\")\n                return True\n        \n        print(\"❌ F-3 FAILED: Missing x5c was accepted\")\n        return False\n        \n    except Exception as e:\n        print(f\"❌ F-3 ERROR: {e}\")\n        return False\n\ndef test_f13_wrong_key_signature() -> bool:\n    \"\"\"Test F-13: Server rejects signatures made with wrong key\"\"\"\n    print(\"\\n🧪 Testing F-13: Wrong Key Signature\")\n    \n    try:\n        challenge, _ = get_registration_challenge(\"test_f13@example.com\", \"none\")\n        client_data_json = create_client_data(challenge)\n        \n        # Create signature with DEADBEEF pattern (indicates wrong key)\n        wrong_key_signature = b'\\xDE\\xAD\\xBE\\xEF' + b'\\x12' * 60\n        attestation_object = create_attestation_object(wrong_key_signature, False)\n        \n        response = requests.post(f\"{SERVER_URL}/attestation/result\", json={\n            \"id\": base64url_encode(b'\\x01' * 32),\n            \"type\": \"public-key\",\n            \"response\": {\n                \"clientDataJSON\": client_data_json,\n                \"attestationObject\": attestation_object\n            }\n        })\n        \n        if response.status_code != 200:\n            error_msg = response.json().get(\"errorMessage\", \"\")\n            if \"Can not validate response signature!\" in error_msg:\n                print(\"✅ F-13 PASSED: Wrong key signature correctly rejected\")\n                return True\n        \n        print(\"❌ F-13 FAILED: Wrong key signature was accepted\")\n        return False\n        \n    except Exception as e:\n        print(f\"❌ F-13 ERROR: {e}\")\n        return False\n\ndef test_valid_registration() -> bool:\n    \"\"\"Test that valid registrations still work\"\"\"\n    print(\"\\n🧪 Testing Valid Registration\")\n    \n    try:\n        challenge, _ = get_registration_challenge(\"valid_user@example.com\", \"none\")\n        client_data_json = create_client_data(challenge)\n        \n        # Create valid attestation\n        attestation_object = create_attestation_object()\n        \n        response = requests.post(f\"{SERVER_URL}/attestation/result\", json={\n            \"id\": base64url_encode(b'\\x01' * 32),\n            \"type\": \"public-key\",\n            \"response\": {\n                \"clientDataJSON\": client_data_json,\n                \"attestationObject\": attestation_object\n            }\n        })\n        \n        if response.status_code == 200:\n            result = response.json()\n            if result.get(\"status\") == \"ok\":\n                print(\"✅ Valid Registration PASSED\")\n                return True\n        \n        print(f\"❌ Valid Registration FAILED: {response.status_code} - {response.text}\")\n        return False\n        \n    except Exception as e:\n        print(f\"❌ Valid Registration ERROR: {e}\")\n        return False\n\ndef test_api_response_format() -> bool:\n    \"\"\"Test that API responses match FIDO specification\"\"\"\n    print(\"\\n🧪 Testing API Response Format\")\n    \n    try:\n        response = requests.post(f\"{SERVER_URL}/attestation/options\", json={\n            \"username\": \"format_test@example.com\",\n            \"displayName\": \"Format Test User\",\n            \"attestation\": \"none\"\n        })\n        \n        if response.status_code != 200:\n            print(f\"❌ API Format FAILED: HTTP {response.status_code}\")\n            return False\n        \n        data = response.json()\n        \n        # Check required fields\n        required_fields = [\"status\", \"errorMessage\", \"rp\", \"user\", \"challenge\", \"pubKeyCredParams\"]\n        for field in required_fields:\n            if field not in data:\n                print(f\"❌ API Format FAILED: Missing field '{field}'\")\n                return False\n        \n        # Check field types\n        if data[\"status\"] != \"ok\":\n            print(f\"❌ API Format FAILED: Invalid status: {data['status']}\")\n            return False\n        \n        if not isinstance(data[\"pubKeyCredParams\"], list) or len(data[\"pubKeyCredParams\"]) == 0:\n            print(\"❌ API Format FAILED: Invalid pubKeyCredParams\")\n            return False\n        \n        print(\"✅ API Response Format PASSED\")\n        return True\n        \n    except Exception as e:\n        print(f\"❌ API Format ERROR: {e}\")\n        return False\n\ndef test_server_health() -> bool:\n    \"\"\"Test server health endpoint\"\"\"\n    print(\"\\n🧪 Testing Server Health\")\n    \n    try:\n        response = requests.get(f\"{SERVER_URL}/health\", timeout=5)\n        \n        if response.status_code == 200:\n            data = response.json()\n            if data.get(\"status\") == \"ok\":\n                print(\"✅ Server Health PASSED\")\n                return True\n        \n        print(f\"❌ Server Health FAILED: {response.status_code}\")\n        return False\n        \n    except Exception as e:\n        print(f\"❌ Server Health ERROR: {e}\")\n        return False\n\ndef main():\n    \"\"\"Run comprehensive conformance test suite\"\"\"\n    print(\"🚀 FIDO2/WebAuthn Conformance Test Suite\")\n    print(f\"Testing server at: {SERVER_URL}\")\n    print(\"=\" * 50)\n    \n    tests = [\n        (\"Server Health\", test_server_health),\n        (\"API Response Format\", test_api_response_format),\n        (\"F-2: Unverifiable Signature\", test_f2_unverifiable_signature),\n        (\"F-3: Missing x5c\", test_f3_missing_x5c),\n        (\"F-13: Wrong Key Signature\", test_f13_wrong_key_signature),\n        (\"Valid Registration\", test_valid_registration),\n    ]\n    \n    passed = 0\n    total = len(tests)\n    \n    for test_name, test_func in tests:\n        try:\n            if test_func():\n                passed += 1\n        except Exception as e:\n            print(f\"❌ {test_name} EXCEPTION: {e}\")\n    \n    print(\"\\n\" + \"=\" * 50)\n    print(f\"📊 FINAL RESULTS: {passed}/{total} tests passed\")\n    \n    if passed == total:\n        print(\"🎉 ALL TESTS PASSED! FIDO conformance fixes are working correctly.\")\n        print(\"✅ Server is ready for full FIDO conformance testing.\")\n        return 0\n    else:\n        print(f\"⚠️  {total - passed} tests failed. Additional fixes may be needed.\")\n        return 1\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n